all_playlists = []
page_index = 0
page_limit = 20
while True:
    resp = apis.spotify.show_playlist_library(access_token=spotify_login, page_index=page_index, page_limit=page_limit)
    # Check if response is a list or has a key
    if isinstance(resp, dict) and 'playlists' in resp:
        playlists_page = resp['playlists']
    elif isinstance(resp, list):
        playlists_page = resp
    else:
        print("Unexpected response:", resp)
        break
    if not playlists_page:
        break
    all_playlists.extend(playlists_page)
    if len(playlists_page) < page_limit:
        break
    page_index += 1

print("Total playlists:", len(all_playlists))
for p in all_playlists:
    print(p)

